import crypto from 'crypto';

/**
 * Pure pairing rules (S2). No @forge/kvs import, so everything here is
 * unit-testable under node --test.
 *
 * A pairing is (inviteToken, installId). installId is 32 lowercase hex
 * characters generated by the installer and cached per browser profile; it is
 * not a UUID, and no second format is accepted anywhere.
 */

export const MAX_PAIRINGS = 10;
export const PAIRING_TTL_FLOOR_SECONDS = 60;
export const INSTALL_ID_RE = /^[a-f0-9]{32}$/;

export function hashToken(raw) {
  return crypto.createHash('sha256').update(String(raw)).digest('hex');
}

/** Short, non-reversible reference used in index keys and admin output. */
export function parentRefOf(raw) {
  return hashToken(raw).slice(0, 16);
}

export function remainingTtlSeconds(expiresAt, now) {
  const remaining = Math.ceil((Number(expiresAt) - Number(now)) / 1000);
  return Math.max(PAIRING_TTL_FLOOR_SECONDS, remaining);
}

/**
 * Pairing identity. The invite is a fixed 64-hex prefix and installId is either
 * 32 hex or empty, so plain concatenation is unambiguous by length.
 */
export function pairingIdFor(inviteToken, installId) {
  return hashToken(`${inviteToken}${installId || ''}`);
}

export function remainingPairings(countFromIndex) {
  const used = Math.max(0, Number(countFromIndex) || 0);
  return Math.max(0, MAX_PAIRINGS - used);
}

export function buildPairingRecord({ inviteToken, installId, userAgent, now, expiresAt }) {
  return {
    pairingId: pairingIdFor(inviteToken, installId),
    inviteTokenRef: parentRefOf(inviteToken),
    installId: installId || '',
    userAgent: userAgent || null,
    state: 'active',
    firstSeenAt: now,
    lastSeenAt: now,
    expiresAt: expiresAt || null,
  };
}

export function pairingKey(pairingId) {
  return `pairings:${pairingId}`;
}

export function pairingIndexKey(inviteTokenRef, pairingId) {
  return `pairingIndex:${inviteTokenRef}:${pairingId}`;
}

export function pairingIndexPrefix(inviteTokenRef) {
  return `pairingIndex:${inviteTokenRef}:`;
}
